#!/usr/bin/env python3
"""Python re-implementation of src/program.cbl (GnuCOBOL 3)."""

import os
import sys

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
ACCOUNTS_PATH = os.path.join(BASE_DIR, "data", "ACCOUNTS.DAT")
BOOKS_PATH = os.path.join(BASE_DIR, "data", "BOOKS.DAT")
TRANSACTIONS_PATH = os.path.join(BASE_DIR, "data", "TRANSACTIONS.DAT")
INPUT_PATH = os.path.join(BASE_DIR, "src", "INPUT.DAT")

ACCOUNT_LEN = 34
BOOK_LEN = 28
TRANSACTION_LEN = 22
INPUT_LEN = 22

MASK64 = (1 << 64) - 1
MOD10_10 = 10 ** 10


class FatalIOError(Exception):
    pass


def display_to_decimal(data, scale):
    """Emulate libcob's cob_decimal_set_display for DISPLAY numerics."""
    size = len(data)
    if data[0] == 255:
        return (10 ** size, scale)
    if data[0] == 0:
        return (-(10 ** size), scale)

    idx = 0
    while size > 1 and (data[idx] & 0x0F) == 0:
        idx += 1
        size -= 1

    n = 0
    for _ in range(size):
        if n:
            n = (n * 10) & MASK64
        n = (n + (data[idx] - ord('0'))) & MASK64
        idx += 1
    return (n, scale)


def trunc_div(value, divisor):
    quotient = abs(value) // divisor
    return -quotient if value < 0 else quotient


def format_account_balance(value):
    if value < 0:
        value = -value
    text = str(value)
    if len(text) > 10:
        text = text[-10:]
    else:
        text = text.zfill(10)
    return text.encode('latin-1')


def move_replace(data):
    """store_common_region's byte normalisation: space and low-value -> '0'."""
    return bytes(ord('0') if b in (0, 32) else b for b in data)


class SequentialFile:
    def __init__(self, path, record_length):
        self.path = path
        self.record_length = record_length
        self.buffer = bytearray(record_length)
        self.handle = None
        self.read_done = False

    def _reset_buffer(self):
        self.buffer = bytearray(self.record_length)

    def open_input(self):
        self.handle = open(self.path, "rb", buffering=0)
        self._reset_buffer()
        self.read_done = False

    def open_io(self):
        self.handle = open(self.path, "r+b", buffering=0)
        self._reset_buffer()
        self.read_done = False

    def read(self):
        self.read_done = False
        chunk = self.handle.read(self.record_length)
        if not chunk:
            return False
        self.buffer[:len(chunk)] = chunk
        if len(chunk) == self.record_length:
            self.read_done = True
        return True

    def rewrite(self):
        was_read = self.read_done
        self.read_done = False
        if not was_read:
            raise FatalIOError(self.path)
        start = self.handle.tell() - self.record_length
        self.handle.seek(start)
        self.handle.write(bytes(self.buffer))
        self.handle.seek(start + self.record_length)

    def close(self):
        if self.handle is not None:
            self.handle.close()
            self.handle = None


def rewrite_or_abort(seqfile):
    """GnuCOBOL aborts the run when REWRITE fails (status 43)."""
    try:
        seqfile.rewrite()
    except FatalIOError:
        raise FatalIOError(seqfile.path)


def validate(buyer, seller, book):
    buyer_found = False
    seller_found = False
    book_found = False
    valid_owner = False

    accounts = SequentialFile(ACCOUNTS_PATH, ACCOUNT_LEN)
    accounts.open_input()
    try:
        while accounts.read():
            account_id = bytes(accounts.buffer[0:4])
            if account_id == buyer:
                buyer_found = True
            if account_id == seller:
                seller_found = True
    finally:
        accounts.close()

    books = SequentialFile(BOOKS_PATH, BOOK_LEN)
    books.open_input()
    try:
        while books.read():
            record = books.buffer
            if bytes(record[0:4]) == book:
                book_found = True
                if bytes(record[24:28]) == seller:
                    valid_owner = True
    finally:
        books.close()

    print(" ")
