    balance_value, balance_scale = display_to_decimal(balance_bytes, 0)
    if balance_scale < amount_scale:
        balance_value *= 10 ** (amount_scale - balance_scale)
        balance_scale = amount_scale

    if add:
        value = balance_value + amount_value
    else:
        value = balance_value - amount_value

    value = trunc_div(value, 10 ** balance_scale)
    if value < 0:
        value = -value
    return value % MOD10_10


def process_transaction(buyer, seller, book, amount_raw):
    amount_display = move_replace(amount_raw)
    ws_amount = amount_display + b"00"
    amount_value, amount_scale = display_to_decimal(ws_amount, 2)

    accounts = SequentialFile(ACCOUNTS_PATH, ACCOUNT_LEN)
    accounts.open_io()
    try:
        while accounts.read():
            record = accounts.buffer
            if bytes(record[0:4]) == buyer:
                record[24:34] = format_account_balance(
                    apply_amount(bytes(record[24:34]), amount_value,
                                 amount_scale, False))
                rewrite_or_abort(accounts)
            if bytes(record[0:4]) == seller:
                record[24:34] = format_account_balance(
                    apply_amount(bytes(record[24:34]), amount_value,
                                 amount_scale, True))
                rewrite_or_abort(accounts)
    finally:
        accounts.close()

    books = SequentialFile(BOOKS_PATH, BOOK_LEN)
    books.open_io()
    try:
        while books.read():
            record = books.buffer
            if bytes(record[0:4]) == book:
                record[24:28] = buyer
                rewrite_or_abort(books)
    finally:
        books.close()

    transaction = book + amount_display + seller + buyer
    with open(TRANSACTIONS_PATH, "ab", buffering=0) as trans:
        trans.write(transaction)

    print("Transaction completed successfully")


def main():
    input_file = SequentialFile(INPUT_PATH, INPUT_LEN)
    input_file.open_input()
    try:
        if not input_file.read():
            print("Error: Input file is empty")
            return 0
        record = bytes(input_file.buffer)
    finally:
        input_file.close()

    buyer = record[0:4]
